package in.agricred.riskservice;
import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/risk") @CrossOrigin(origins="*") public class RiskController{
record Assessment(String email,Double requestedAmount,Integer tenureMonths,String purpose,Double landAcres,String crop,String season,Double annualIncome,Double existingDebt,Integer latePayments,Integer onTimePayments,Double expectedIncome){}
@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","risk-service");}
@PostMapping("/assess") public Map<String,Object> assess(@RequestBody Assessment a){List<Map<String,Object>> factors=new ArrayList<>();double score=50;double land=a.landAcres()==null?0:Math.max(0,a.landAcres());double income=a.annualIncome()==null?0:Math.max(0,a.annualIncome());double debt=a.existingDebt()==null?0:Math.max(0,a.existingDebt());int late=a.latePayments()==null?0:Math.max(0,a.latePayments());int ontime=a.onTimePayments()==null?0:Math.max(0,a.onTimePayments());double req=a.requestedAmount()==null?0:Math.max(0,a.requestedAmount());
if(land>=5){score+=12;factors.add(f("Land holding",12,"Land area is at least 5 acres"));}else if(land>=2){score+=7;factors.add(f("Land holding",7,"Land area is 2–4.99 acres"));}else{score-=5;factors.add(f("Land holding",-5,"Small land holding increases repayment sensitivity"));}
if(income>=300000){score+=15;factors.add(f("Annual income",15,"Reported annual income is ₹3 lakh or more"));}else if(income>=150000){score+=8;factors.add(f("Annual income",8,"Reported annual income is ₹1.5–3 lakh"));}else{score-=8;factors.add(f("Annual income",-8,"Lower reported annual income limits repayment capacity"));}
if(late==0){score+=10;factors.add(f("Repayment history",10,"No late payments reported"));}else{int impact=Math.min(20,late*5);score-=impact;factors.add(f("Repayment history",-impact,late+" late payment(s) reported"));}if(ontime>0){int bonus=Math.min(8,ontime*2);score+=bonus;factors.add(f("On-time payments",bonus,ontime+" on-time payment(s) reported"));}
double debtRatio=income>0?debt/income:1;if(debtRatio<0.2){score+=8;factors.add(f("Existing obligations",8,"Existing debt is below 20% of reported annual income"));}else if(debtRatio>0.5){score-=12;factors.add(f("Existing obligations",-12,"Existing debt exceeds 50% of reported annual income"));}else{factors.add(f("Existing obligations",0,"Moderate existing debt relative to income"));}
String crop=Objects.toString(a.crop(),"").toLowerCase();String season=Objects.toString(a.season(),"").toLowerCase();if(!crop.isBlank()){double bonus=(season.contains("harvest")||season.contains("post-harvest"))?6:0;score+=bonus;factors.add(f("Crop and season",(int)bonus,bonus>0?"Harvest/post-harvest season may align cash flow":"Crop is recorded; seasonal income timing should be verified"));}else factors.add(f("Crop and season",-3,"Crop information is missing; verify before a lending decision"));
if(req>0&&income>0&&req>income*2){score-=10;factors.add(f("Requested amount",-10,"Requested amount is more than twice reported annual income"));}else factors.add(f("Requested amount",0,"Request checked against reported income"));score=Math.max(0,Math.min(100,score));String category=score>=75?"LOW RISK":score>=55?"MODERATE RISK":"HIGH RISK";double ratio=score>=75?0.8:score>=55?0.5:score>=35?0.25:0.1;double affordability=income*0.8;double landCap=land*150000;double eligible=Math.min(req*ratio,Math.min(affordability,landCap));eligible=Math.max(0,Math.floor(eligible/1000)*1000);String recommendation=eligible>=req?"Potentially eligible for the requested amount, subject to document and policy checks.":eligible>0?"Consider a reduced amount based on the reported profile; verify documents and seasonal cash flow.":"Insufficient information or affordability under this baseline; request verification and human review.";return Map.of("score",Math.round(score),"category",category,"eligibilityPercent",Math.round(req>0?eligible/req*100:0),"requestedAmount",req,"eligibleAmount",eligible,"recommendation",recommendation,"factors",factors,"model","Explainable rules baseline v1","disclaimer","Decision support only. Values are based on user-reported data, not bureau verification or a validated credit model.");}
private Map<String,Object> f(String name,int impact,String explanation){return Map.of("factor",name,"impact",impact,"explanation",explanation);}}
